function uninstall(names, callback) {
  callback = utils.defineCallback(callback);
  if (_.isString(names)) {
    names = [ names ];
  }
  var errs = [ ];
  var numPlugins = 0;
  names.forEach(function(name) {
    rimraf(pluginsDir + "/" + name, cb);
  });

  function cb(err) {
    if (err) {
      errs.push(err);
    }
    if (++numPlugins === names.length) {
      return callback(errs.length === 0 ? null : errs);
    }
  }
}

